[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/MessageStore.java", "content": "package com.example.contact;

import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * Keeps the messages that have been sent, newest first.
 * <p>
 * The store lives in the Vaadin session, so leaving the contact view and coming
 * back still shows everything that was sent. Nothing is written to disk.
 */
public class MessageStore {

    /** Used when there is no session at hand, e.g. in a plain unit test. */
    private static final MessageStore FALLBACK = new MessageStore();

    private final List<ContactMessage> messages = new ArrayList<>();

    public static MessageStore current() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            return FALLBACK;
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    /** The messages sent so far, newest first. */
    public synchronized List<ContactMessage> messages() {
        return List.copyOf(messages);
    }

    public synchronized void add(ContactMessage message) {
        messages.add(0, message);
    }
}
