+        email().setValue(emailValue);
+        phone().setValue(phoneValue);
+        message().setValue(messageValue);
+    }
+
+    @Test
+    void contactView_showsHeadingLinkAndEmptyForm() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(aboutLink()).isVisible();
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+    }
+
+    @Test
+    void emptyForm_send_showsTheErrorsAndSendsNothing() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        assertFalse(new NotificationElement(page).isOpen(), "nothing may be sent");
+        GridElement.get(page).assertRowCount(0);
+        send().assertEnabled();
+    }
+
+    @Test
+    void invalidEmail_send_showsTheEmailError() {
+        fillIn("Ada", "ada@", "", "Hello there");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Ada");
+        message().assertValue("Hello there");
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void tooLongMessage_send_showsTheLengthError() {
+        fillIn("Ada", "ada@example.com", "", "x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void validForm_send_notifiesListsAndEmptiesTheForm() {
+        fillIn("Ada Lovelace", "ada@example.com", "", "Hello there");
+        send().click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        assertThat(grid.findRow(0).orElseThrow().getCell(0).getCellContentLocator())
+                .hasText("Ada Lovelace");
+        assertThat(grid.findRow(0).orElseThrow().getCell(1).getCellContentLocator())
+                .hasText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+
+        send().assertDisabled();
+        name().getInputLocator().pressSequentially("G");
+        send().assertEnabled();
+    }
+
+    @Test
+    void phoneOnly_typedByHand_andSentWithEnter() {
+        name().getInputLocator().pressSequentially("Grace");
+        phone().getInputLocator().pressSequentially("040 1234567");
+        message().getInputLocator().pressSequentially("Call me");
+        message().getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        assertThat(grid.findRow(0).orElseThrow().getCell(0).getCellContentLocator())
+                .hasText("Grace");
+    }
+
+    @Test
+    void aboutLink_navigatesWithoutReloadingThePage_andListSurvives() {
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        send().click();
+        GridElement.get(page).assertRowCount(1);
+
+        // Anything the page keeps in memory survives a client-side navigation.
+        page.evaluate("() => { window.__notReloaded = true; }");
+
+        aboutLink().click();
+        assertThat(page.locator("h1")).hasText("About");
+        assertEquals(Boolean.TRUE, page.evaluate("() => window.__notReloaded === true"),
+                "the About link must not reload the page");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("Contact")).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertFalse(new DialogElement(page).isVisible(), "no dialog may appear");
+    }
+
+    @Test
+    void dirtyForm_keepEditing_staysOnTheView() {
+        name().setValue("Ada");
+        aboutLink().click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(dialog.getLocator(), "Keep editing").click();
+
+        dialog.assertClosed();
+        assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+        assertTrue(page.url().endsWith("/contact"), "the address bar stays on the view: " + page.url());
+    }
+
+    @Test
+    void dirtyForm_discard_navigatesOn() {
+        message().setValue("Half-written");
+        aboutLink().click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(dialog.getLocator(), "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertTrue(page.url().endsWith("/about"), "the navigation went ahead: " + page.url());
+    }
+
+    @Test
+    void usingTheView_logsNoClientSideErrors() {
+        List<String> errors = new ArrayList<>();
+        page.onConsoleMessage(consoleMessage -> {
+            if ("error".equals(consoleMessage.type())
+                    && !consoleMessage.text().contains("favicon")) {
+                errors.add(consoleMessage.text());
+            }
+        });
+        page.reload();
+
+        send().click();
+        name().assertInvalid();
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        send().click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        name().setValue("Grace");
+        aboutLink().click();
+        ButtonElement.getByText(new DialogElement(page).getLocator(), "Discard").click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        assertTrue(errors.isEmpty(), () -> "client-side errors: " + errors);
+    }
+}
