+        assertEquals(ContactView.CONTACT_REQUIRED, email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals(ContactView.MESSAGE_REQUIRED, message.getErrorMessage());
+
+        assertFalse(find(Notification.class).exists(), "nothing may be sent");
+        assertEquals(0, test(grid()).size());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidEmail_send_marksEmailInvalidAndKeepsInput() {
+        fillIn("Ada", "not-an-email", "", "Hello there");
