+
+        assertTrue(message.isInvalid());
+        assertEquals(ContactView.MESSAGE_REQUIRED, message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessage_send_marksMessageInvalid() {
