+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void phoneOnly_send_isEnough() {
+        fillIn("Ada", "", "+358 40 1234567", "Call me");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void emailOnly_send_isEnough() {
+        fillIn("Ada", "ada@example.com", "", "Mail me");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_send_notifiesListsAndEmptiesTheForm() {
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        test(send).click();
+
+        assertTrue(find(Notification.class).all().stream()
+                .anyMatch(n -> test(n).getText().contains("Message sent")),
+                "a notification containing 'Message sent' must appear");
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(send.isEnabled(), "Send is disabled right after a successful send");
+        test(name).setValue("Grace");
+        assertTrue(send.isEnabled(), "editing a field enables Send again");
+    }
+
+    @Test
+    void send_isEnabledAgainAfterEditingAnyField() {
+        for (Runnable edit : new Runnable[] { () -> test(name).setValue("Grace"),
+                () -> test(email).setValue("grace@example.com"),
+                () -> test(phone).setValue("123"), () -> test(message).setValue("Hi") }) {
+            fillIn("Ada", "ada@example.com", "", "Hello");
+            test(send).click();
+            assertFalse(send.isEnabled());
+            edit.run();
+            assertTrue(send.isEnabled());
+            fillIn("", "", "", "");
+        }
+    }
+
+    @Test
+    void enterKey_sendsTheMessage() {
+        fillIn("Ada", "ada@example.com", "", "Sent with Enter");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Sent with Enter", test(grid()).getCellText(0, 1));
+        assertEquals("", message.getValue());
+    }
+
+    @Test
+    void severalMessages_areListedNewestFirst() {
+        fillIn("First", "first@example.com", "", "Message one");
+        test(send).click();
+        fillIn("Second", "second@example.com", "", "Message two");
+        test(send).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Second", test(grid()).getCellText(0, 0));
+        assertEquals("First", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void sentMessages_surviveLeavingAndComingBack() {
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        test(send).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        locateFields();
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertFalse(find(Dialog.class).exists(), "no dialog may appear for an empty form");
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void dirtyForm_keepEditing_staysOnTheView() {
